export function createUiHarnessHost(): UiHarnessHost {
  const listeners = new Set<(event: HostEvent) => void>();
  // Like a migrated install: no app-wide agent, so the bundle .env wins.
  let settings: AppSettings = { ...cloneDefaultAppSettings(), dashBoredAgent: null };
  let persistedConfig = structuredClone(initialConfig);
  let configRevision = 1;
  let snapshotRevision = 1;
  let currentDiagnostics: Diagnostic[] = [];
  let updateOverride: Partial<UpdateState> | null = null;
  let packageUpdates: PackageUpdateState = structuredClone(INITIAL_PACKAGE_UPDATE_STATE);
  const packageUpdateCommands: PackageUpdateCommand[] = [];
  const publishPackageUpdates = (patch: Partial<PackageUpdateState>): void => {
    packageUpdates = { ...packageUpdates, ...structuredClone(patch) };
    emit({ type: "package-updates", state: structuredClone(packageUpdates) });
  };
  const packageOperations: unknown[] = [];
  let notifications: NotificationState = structuredClone(INITIAL_NOTIFICATION_STATE);
  let notificationSequence = 0;
  let notificationIds = 0;
  const notificationCommands: NotificationCommand[] = [];
  const publishNotifications = (next: Pick<NotificationState, "entries"> & Partial<NotificationState>): void => {
    notifications = { entries: next.entries, history: next.history ?? notifications.history };
    emit({ type: "notifications", state: structuredClone(notifications) });
  };
  const raiseNotification = (input: FixtureNotificationRaise): NotificationEntry => {
    const configPath = input.configPath === undefined ? CONFIG_PATH : input.configPath;
    publishNotifications({ entries: coalesceFixtureNotification(notifications.entries, {
      ...input,
      configPath,
      dashboardName: input.dashboardName !== undefined ? input.dashboardName : configPath === null ? null : persistedConfig.name,
    }, {
      id: `fixture-notification-${++notificationIds}`,
      now: new Date(),
      presentation: () => ++notificationSequence,
    }) });
    return structuredClone(notifications.entries[0]!);
  };
  const processSnapshots = new Map<string, ProcessSnapshot>();
  const files = new Map<string, string>([
    ["README.md", "# Fixture document\n\nThis file is loaded by the Markdown component.\n"],
    [".dash-bored/.env", "DASH_BORED_AGENT=bundle-agent\n"],
  ]);
  const emit = (event: HostEvent): void => listeners.forEach((listener) => listener(event));
  const snapshot = (): ProjectSnapshot => {
  const tree = resolveFixtureNode(persistedConfig.root);
  const environmentByNode: NonNullable<ProjectSnapshot["environmentByNode"]> = {};
  const bundleAgent = envEntries(parseEnv(files.get(".dash-bored/.env") ?? ""))
    .find(({ entry }) => entry.key === "DASH_BORED_AGENT")?.entry.value;
  const visitEnvironment = (node: ResolvedComponentNode): void => {
    environmentByNode[node.id] = {
      values: [{
        key: "DASH_BORED_AGENT",
        value: settings.dashBoredAgent ?? bundleAgent ?? "",
        source: settings.dashBoredAgent !== null ? "app" : bundleAgent !== undefined ? "bundle" : "unset",
      }],
    };
    for (const edge of childEdges(node.children)) visitEnvironment(edge.node as ResolvedComponentNode);
  };
  visitEnvironment(tree);
  return {
    themeCatalog: structuredClone(FIXTURE_THEMES),
    animationCatalog: structuredClone(FIXTURE_ANIMATIONS),
    environmentByNode,
    projectRoot: PROJECT_ROOT,
    configPath: CONFIG_PATH,
    dashboardName: persistedConfig.name,
    iconDataUrl: null,
    config: structuredClone(persistedConfig),
    configRevision: `ui-harness-${configRevision}`,
    componentCatalog: structuredClone(catalog),
    componentTemplates: coreFixture.templates,
    trusted: true,
    requestedPermissions: validateFixtureDraft(persistedConfig).requestedPermissions,
    tree,
    components: validateFixtureDraft(persistedConfig).components,
    processes: [...processSnapshots.values()].map((process) => structuredClone(process)),
    diagnostics: structuredClone(currentDiagnostics),
    revision: snapshotRevision,
  };
  };
  const emitSnapshot = (): ProjectSnapshot => {
    const currentSnapshot = snapshot();
    emit({ type: "snapshot", snapshot: currentSnapshot });
    return currentSnapshot;
  };
  const bundleAgent = (): string | null => envEntries(parseEnv(files.get(".dash-bored/.env") ?? ""))
    .find(({ entry }) => entry.key === "DASH_BORED_AGENT")?.entry.value.trim() || null;
  const agents = createFixtureAgents({
    projectRoot: PROJECT_ROOT,
    configPath: CONFIG_PATH,
    appAgent: () => settings.dashBoredAgent,
    enabledAgentIds: () => settings.enabledAgentIds,
    projectAgent: bundleAgent,
    publish: (task) => emit({ type: "agent-task", task }),
  });
  const renderComponentPrompt = (request: ComponentAgentRequest) => {
    const nodes = request.nodeIds.map((nodeId) => findResolvedNode(snapshot().tree!, nodeId));
    const [node] = nodes;
    if (!node || nodes.some((target) => target === null)) throw new Error("That component is no longer present.");
    const templates = fixturePromptTemplates();
    const prepared = prepareAgentPrompt({ templates, diagnostics: [] }, {
      ...(request.template ? { template: request.template } : {}),
      input: request.prompt,
      ...(request.vars ? { vars: request.vars } : {}),
      projectRoot: "/ui-harness",
      configPath: CONFIG_PATH,
      configDirectory: PROJECT_ROOT,
      components: (nodes as ResolvedComponentNode[]).map(promptComponent),
      allowEmptyInput: true,
    });
    return { node, templates, ...prepared };
  };
  const launchComponent = (request: ComponentAgentRequest & { agent?: AgentCommandChoice }) => {
    const { node, template, prompt } = renderComponentPrompt(request);
    return agents.launch({
      purpose: template.scope === "dashboard" ? "edit" : "project",
      template: template.name,
      request: request.prompt.trim() || template.description || template.name,
      prompt,
      componentPath: componentPath(node),
      ...(request.agent ? { agent: request.agent } : {}),
      ...(request.config ? { config: request.config } : {}),
    });
  };

  return {
    registerComponentFixture(item, component) {
      catalog.push(structuredClone(item));
      coreFixture.components.push(structuredClone(component));
      emitSnapshot();
    },
    registerTemplateFixture(template) {
      coreFixture.templates.push(structuredClone(template));
      emitSnapshot();
    },
    finishAgentTask: agents.finishAgentTask,
    appendAgentMessage: agents.appendAgentMessage,
    requestAgentPermission: agents.requestAgentPermission,
    patchAgentTask: agents.patchAgentTask,
    getAgentTaskCommands: agents.getAgentTaskCommands,
    setAgentCommandLatency: agents.setAgentCommandLatency,
    setDetectedAgents: agents.setDetectedAgents,
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    getPersistedConfig() { return structuredClone(persistedConfig); },
    setProcessSnapshot(process) {
      processSnapshots.set(process.id, structuredClone(process));
      emit({ type: "process", process: structuredClone(process) });
    },
    async getSnapshot() { return snapshot(); },
    async getThemes() { return structuredClone(FIXTURE_APPLICATION_THEMES); },
    async readAnimation(reference: string) {
      const item = FIXTURE_ANIMATIONS.find((candidate) => candidate.reference === reference);
      const manifest = builtinAnimation(reference) ?? item?.manifest;
      if (!manifest) throw new Error(`${reference}: ${item?.error ?? "animation not found."}`);
      return structuredClone(manifest);
    },
    async getUpdateState(): Promise<UpdateState> { return { currentVersion: "0.2.6", settings: { channel: "canary" as const, automaticChecks: true }, release: null, receipt: null, dashboards: [], phase: "idle" as const, message: "UI fixture: no network check performed.", ...structuredClone(updateOverride ?? {}) }; },
    async updateAction(action) {
      if (action.type === "settings") updateOverride = { ...updateOverride, settings: action.settings };
      if (action.type === "check") updateOverride = { ...updateOverride, checkedAt: new Date().toISOString() };
      return { ...await this.getUpdateState(), message: "UI fixture: update action received; no installation performed." };
    },
    setUpdateState(state) { updateOverride = state && structuredClone(state); },
    async getPackageUpdates() { return structuredClone(packageUpdates); },
    async packageUpdateCommand(command) {
      if (packageUpdates.phase !== "idle") throw new Error("A package check or update is already running.");
      packageUpdateCommands.push(structuredClone(command));
      if (command.type === "check") {
        publishPackageUpdates({ phase: "checking", problem: "" });
        setTimeout(() => publishPackageUpdates({
          phase: "idle", checkedAt: new Date().toISOString(), packages: fixturePackageUpdates(persistedConfig.name),
          message: "UI fixture: no network check performed.",
        }), 150);
        return;
      }
      const ids = new Set(command.ids);
      publishPackageUpdates({ phase: "updating", updating: command.ids, message: "" });
      setTimeout(() => publishPackageUpdates({
        phase: "idle", updating: [],
        packages: packageUpdates.packages.map((item) => ids.has(item.id) && item.latest
          ? { ...item, current: item.latest, status: "current" as const, changesUrl: undefined } : item),
        message: "UI fixture: package update received; no checkout changed.",
      }), 150);
    },
    setPackageUpdates(state) {
      packageUpdates = structuredClone(INITIAL_PACKAGE_UPDATE_STATE);
      publishPackageUpdates(state ?? {});
    },
    getPackageUpdateCommands() { return structuredClone(packageUpdateCommands); },
    async getNotifications() { return structuredClone(notifications); },
    async notificationCommand(command) {
      notificationCommands.push(structuredClone(command));
      if (command.type !== "notify") {
        publishNotifications(applyNotificationCommand(notifications, command));
        return;
      }
      const tree = snapshot().tree;
      const label = tree ? dashboardNodeEntries(tree).find((entry) => entry.node.id === command.nodeId)?.label : undefined;
      if (label === undefined) throw new Error(`No component with id ${command.nodeId} exists in the open dashboard.`);
      raiseNotification({
        key: `notify:${CONFIG_PATH}:${command.nodeId}:${command.itemId ?? ""}`,
        kind: "notify",
        title: label,
        message: command.message,
        target: { kind: "node", nodeId: command.nodeId, ...(command.itemId ? { itemId: command.itemId } : {}) },
      });
    },
    raiseNotification,
    resolveNotification(key) {
      const closedAt = new Date().toISOString();
      publishNotifications({
        entries: notifications.entries.filter((entry) => entry.key !== key),
        history: [
          ...notifications.entries.filter((entry) => entry.key === key).map((entry) => ({ ...entry, closedAt, closedBy: "cleared" as const })),
          ...notifications.history,
        ],
      });
    },
    getNotificationCommands() { return structuredClone(notificationCommands); },
    async getAppSettings() { return structuredClone(settings); },
    async updateAppSettings(next) { settings = structuredClone(next); emitSnapshot(); return structuredClone(settings); },
    async getPromptTemplates(nodeId: string) {
      if (!findResolvedNode(snapshot().tree!, nodeId)) throw new Error("The prompt target is no longer present.");
      return promptTemplateSummaries(fixturePromptTemplates());
    },
    async previewComponentAgent(request: ComponentAgentRequest) {
      // The shipped defaults plus one bundle template with a declared var.
      const { templates, template, prompt } = renderComponentPrompt(request);
      return { template: promptTemplateSummary(template), prompt, templates: promptTemplateSummaries(templates), agents: await agents.getAgentOptions(CONFIG_PATH) };
    },
    async launchAgent(request) {
      if (request.kind === "diagnostics") {
        const prompt = "Fix dashboard configuration diagnostics.";
        return agents.launch({ purpose: "repair", request: prompt, prompt, componentPath: `${CONFIG_PATH}#diagnostics` });
      }
      if (request.kind === "creation") {
        return agents.launch({ purpose: "edit", template: "dashboard", request: request.prompt, prompt: request.prompt, componentPath: `${CONFIG_PATH}#create` });
      }
      return launchComponent(request);
    },
    async repairInstalledTools() {
      currentDiagnostics = [];
      emitSnapshot();
      return { conflictsRemain: false };
    },
    async manageExternalComponent(operation) {
      packageOperations.push({ kind: "external", ...operation });
      emitSnapshot();
      return { message: `Ran external ${operation.op}.` };
    },
    async manageThemePackage(operation) {
      packageOperations.push({ kind: "theme", ...operation });
      return { message: `Ran theme ${operation.op}.` };
    },
    getPackageOperations() { return structuredClone(packageOperations); },
    getAgentTasks: agents.getAgentTasks,
    getAgentOptions: agents.getAgentOptions,
    agentTaskCommand: agents.agentTaskCommand,
    async setDiagnostics(next) {
      currentDiagnostics = structuredClone(next);
      emitSnapshot();
    },
    async listProjects() { return [project(persistedConfig)]; },
    async moveProject() { return [project(persistedConfig)]; },
    async getProjectOutline(_project: ProjectListItem): Promise<ProjectOutline> {
      return { ...project(persistedConfig), tree: resolveFixtureNode(persistedConfig.root), diagnostics: [] };
    },
    async chooseProject() { emitSnapshot(); return { opened: true }; },
    async openProject(_project: ProjectTarget) { emitSnapshot(); },
    async getProjectDeletionPreview(_project: ProjectListItem): Promise<ProjectDeletionPreview> {
      return { ...project(persistedConfig), filesDirectory: PROJECT_ROOT, filesExist: false, dependencies: [], analysisComplete: true, analysisIssues: [] };
    },
    async deleteProject(_project: ProjectListItem, _removeFiles: boolean) { emitSnapshot(); },
    async setTrust(_trusted: boolean) { emitSnapshot(); },
    async reloadProject() { emitSnapshot(); },
    async focusWindow() { /* Native window activation is verified in the dev app. */ },
    async getDashboardConfigSource(_configPath?: string): Promise<DashboardConfigSource> {
      return {
        configPath: CONFIG_PATH,
        config: structuredClone(persistedConfig),
        configRevision: `ui-harness-${configRevision}`,
        componentCatalog: structuredClone(catalog),
    componentTemplates: coreFixture.templates,
      };
    },
    async validateDashboardDraft(config: DashboardConfig, _configPath?: string, _sourceNodeId?: string): Promise<DashboardDraftValidation> {
      return validateFixtureDraft(structuredClone(config));
    },
    async validateComponentProps(reference: string, props: Record<string, unknown>): Promise<ComponentPropsValidation> {
      const item = catalog.find((entry) => entry.reference === reference);
      if (!item?.manifest) return { ok: false, diagnostics: [fixtureDiagnostic("COMPONENT_UNAVAILABLE", "That component is not available.", reference)] };
      const validate = ajv.compile(item.manifest.propsSchema);
      return validate(props)
        ? { ok: true, diagnostics: [] }
        : { ok: false, diagnostics: (validate.errors ?? []).map((error) => fixtureSchemaDiagnostic(error, "props", "COMPONENT_PROPS_INVALID")) };
    },
    async saveDashboardConfig(config: DashboardConfig, expectedRevision: string, _configPath?: string) {
      if (expectedRevision !== `ui-harness-${configRevision}`) {
        throw new Error("DASHBOARD_CONFIG_CONFLICT: dash-bored.yaml changed after editing started. Cancel this draft and reopen edit mode before saving.");
      }
      const validation = validateFixtureDraft(structuredClone(config));
      if (!validation.ok) throw new Error(`DASHBOARD_CONFIG_INVALID: ${validation.diagnostics[0]?.message ?? "The dashboard draft is invalid."}`);
      persistedConfig = structuredClone(config);
      configRevision += 1;
      snapshotRevision += 1;
      emitSnapshot();
    },
    async processCommand(nodeId: string, command: ProcessCommand): Promise<ProcessSnapshot> {
      // Like the desktop host, only commands that change a process push it.
      if (command.type === "write" || command.type === "resize") {
        return processSnapshots.get(nodeId)
          ?? { id: nodeId, phase: "idle", pid: null, exitCode: null, signal: null, logs: [] };
      }
      const process: ProcessSnapshot = { id: nodeId, phase: "idle", pid: null, exitCode: null, signal: null, logs: [] };
      processSnapshots.set(nodeId, process);
      emit({ type: "process", process });
      return process;
    },
    async readTextFile(request: FileReadRequest) {
      const content = files.get(request.path);
      if (content === undefined) throw new Error(`Fixture file not found: ${request.path}`);
      return content;
    },
    async writeTextFile(request: FileWriteRequest) {
      files.set(request.path, request.content);
    },
    async httpRequest(_request: HttpRequest): Promise<HttpResponsePayload> {
      return { status: 204, headers: {}, body: "" };
    },
    async runShell(_request: ShellRunRequest): Promise<ShellRunResult> {
      return { exitCode: 0, signal: null, stdout: "UI harness: no command was run.", stderr: "", timedOut: false };
    },
  };
}
